+import { parsePagination, paginatedResponse } from './pagination';
+
+describe('parsePagination', () => {
+  it('usa page=1 y limit=20 por defecto', () => {
+    expect(parsePagination(undefined, undefined)).toEqual({ page: 1, limit: 20, from: 0, to: 19 });
+  });
+
